pub fn get_greenplum_root_grammar_id() -> GrammarId {
    GrammarId(5453)
}
pub fn get_greenplum_root_grammar_table() -> RootGrammar {
    RootGrammar {
        grammar_id: get_greenplum_root_grammar_id(),
        tables: &GREENPLUM_TABLES,
    }
}
pub fn get_greenplum_root_grammar() -> RootGrammar {
    get_greenplum_root_grammar_table()
}
